{
  "title": "The Mirror Rescue of Ruined Kest",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a cracked map at the edge of the ruined city.",
      "visual_description": "Mara stands on a crumbling wall, unrolling a stained parchment while the broken towers of Kest loom through fog.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "Glass Diver surfaces from a mirror pool, ready to begin.",
      "visual_description": "Glass Diver climbs out of a shattered mirror lying in rubble, helmet dripping with silvery liquid, coat reflecting distant fires.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 3,
      "caption": "Oracle Lamp flickers a warning about the castle gates.",
      "visual_description": "Oracle Lamp sits on a fallen pillar, its single flame-eye casting anxious shadows as it gazes toward the massive iron gates ahead.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "Tin Fox scampers ahead to scout the first courtyard.",
      "visual_description": "Tin Fox darts between broken cobblestones, its key-wind tail spinning, blue eyes scanning the empty space beneath torn royal banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "Sleeping Tax Collector snores beside the gatehouse.",
      "visual_description": "Sleeping Tax Collector leans against a stone arch, ledger under head, stamped papers fluttering from his sleeves as the group approaches.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "Mara marks a safe path through the gatehouse rubble.",
      "visual_description": "Mara draws a quick route in her notebook while standing near a fallen gate, ink on her fingers, compass swinging.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Glass Diver peers through a barred window into a dark tower.",
      "visual_description": "Glass Diver presses his helmet against iron bars, his reflection distorting as he scans the cursed tower interior for traps.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Oracle Lamp warns of a patrol rounding the corner.",
      "visual_description": "Oracle Lamp's flame dims suddenly as it whispers, its glow revealing armored boots approaching from a side street.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "Tin Fox leads the group into a narrow alley to hide.",
      "visual_description": "Tin Fox squeezes through a gap in a wall, tail wagging urgently as Mara and Glass Diver follow into the shadows.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "Sleeping Tax Collector stirs and drops a cursed key.",
      "visual_description": "Sleeping Tax Collector rolls over in his sleep, dislodging a rusted key from his belt that clatters onto the stone floor.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver retrieves the key and unlocks a magic door.",
      "visual_description": "Glass Diver bends down, scoops the key, and inserts it into an ornate door that glows faintly as it swings open.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara reads a faded sign to confirm the escape route.",
      "visual_description": "Mara brushes moss from a stone plaque near the door, her compass needle spinning as she deciphers old directions.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "Tin Fox sniffs a draft from the tunnel beyond the door.",
      "visual_description": "Tin Fox stands at the threshold, nostrils flaring, blue eyes reflecting the dark tunnel ahead.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Oracle Lamp lights the way through the underground passage.",
      "visual_description": "Oracle Lamp floats forward, its single eye casting a warm glow on damp stone walls lined with old roots.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Sleeping Tax Collector wanders into the tunnel, still half-asleep.",
      "visual_description": "Sleeping Tax Collector stumbles after the group, ledger tucked under arm, mumbling about unpaid tolls.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "The group emerges onto a bridge overlooking the ruined city.",
      "visual_description": "Mara, Glass Diver, Oracle Lamp, Tin Fox, and Sleeping Tax Collector step out onto a stone bridge arching over a dry moat, with the city burning behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "Armored patrols shout from the city walls, but the group is already safe.",
      "visual_description": "Distant figures in armor stand on the wall, pointing, but the bridge is long and the group is far ahead under a pale sky.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "Mara folds her map as they cross the bridge to freedom.",
      "visual_description": "Mara rolls up her map and smiles, the bridge behind them crumbling slowly, the rescue complete.",
      "characters": ["mara_the_cartographer"]
    }
  ],
  "gate_token": "yeTfbvnHjJP9eQ-ZFle76g"
}

